def test_all_37_names_and_222_four_field_inputs_are_preserved():
    assert tuple((c.name, c.values) for c in CASES) == EXPECTED
    assert len(CASES) == 37 and sum(len(c.values) for c in CASES) == 222
    assert len({c.name for c in CASES}) == 37
    assert [f.name for f in fields(CASES[0])] == ["name", "values"]


@pytest.mark.parametrize("period", ("day", "m60", "m90", "m120"))
def test_four_period_inputs_only_change_time_format(period):
    assert PERIODS == ("day", "m60", "m90", "m120")
    assert DATES[:5] == ("2023-01-03", "2023-01-04", "2023-01-05", "2023-01-06", "2023-01-09")
    for case, (name, values) in zip(CASES, EXPECTED, strict=True):
        assert case.name == name
        actual = case.inputs(period)
        for i, ((close, dif, dea, hist), row) in enumerate(zip(values, actual, strict=True)):
            assert row == dict(time=DATES[i] if period == "day" else DATES[i]+"T15:00:00+08:00",
                               close=close, dif=dif, dea=dea, hist=hist, completed=True)


def test_case_and_returned_inputs_are_isolated():
    with pytest.raises(FrozenInstanceError): CASES[0].name = "changed"
    first = CASES[0].inputs("day")
    first[0]["close"] = -999
    assert CASES[0].inputs("day")[0]["close"] == 100
    assert CASES[1].values[0] == (100, 50, 49, 2)


@pytest.mark.parametrize("period", ["m30", "DAY", None, True])
def test_unsupported_period_is_rejected(period):
    with pytest.raises(ValueError): CASES[0].inputs(period)


def assert_independent_material(source):
    tree = ast.parse(source)
    for item in ast.walk(tree):
        if isinstance(item, ast.ImportFrom):
            assert item.level == 0  # No relative research/product dependencies.
            modules = [item.module]
        elif isinstance(item, ast.Import):
            modules = [alias.name for alias in item.names]
        else:
            continue
        assert all(module.split(".")[0] in sys.stdlib_module_names for module in modules)
    assert not any(isinstance(n, ast.Call) and isinstance(n.func, ast.Name)
                   and n.func.id in {"open", "exec", "eval", "__import__"} for n in ast.walk(tree))


def test_input_material_does_not_depend_on_product_or_research_code():
    assert_independent_material(Path(__file__).with_name("xxm_product_v1_cases.py").read_text())


@pytest.mark.parametrize("source", [
    "from dataclasses import dataclass\nfrom typing import Optional",
    "import typing\nfrom fractions import Fraction",
    "from __future__ import annotations\nimport dataclasses",
])
def test_independent_material_allows_normal_standard_library_imports(source):
    assert_independent_material(source)


@pytest.mark.parametrize("source", [
    "from goldenshare_technical_indicators.xxm.spec import MAIN_SPEC",
    "from scripts.research.index_market.tests.xxm_product_v1_cases import CASES",
])
def test_material_rejects_product_and_research_dependencies(source):
    with pytest.raises(AssertionError):
        assert_independent_material(source)
